const jdBuf = await this.helpers.getBinaryDataBuffer(0, 'job_description');
const jdText = jdBuf.toString('utf8');
const resumeBuf = await this.helpers.getBinaryDataBuffer(0, 'resume');
const data = await this.helpers.prepareBinaryData(resumeBuf, 'resume.zip', 'application/zip');
data.fileName = 'resume.zip';
data.fileExtension = 'zip';
data.mimeType = 'application/zip';
return [{ json: { jdText }, binary: { data } }];

const item = $input.first();
const keys = Object.keys(item.binary || {});
const fullPath = (b) => ((b.directory ? b.directory + '/' : '') + (b.fileName || '')).replace(/^[/]+/, '');
const key = keys.find((k) => fullPath(item.binary[k]).endsWith('word/document.xml') || (item.binary[k].fileName || '').endsWith('word/document.xml'));
if (!key) throw new Error('Could not find word/document.xml in the unzipped resume - is it a valid .docx file? Found entries: ' + (keys.map((k) => fullPath(item.binary[k])).join(', ') || 'none'));
const buf = await this.helpers.getBinaryDataBuffer(0, key);
let xml = buf.toString('utf8');
xml = xml.replace(/<\/w:p>/g, '\n').replace(/<w:tab\/>/g, '\t').replace(/<w:br\/>/g, '\n');
let text = xml.replace(/<[^>]+>/g, '');
text = text.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'");
text = text.replace(/\n{3,}/g, '\n\n').trim();
return [{ json: { resumeText: text, jdText: $('Read Job Description').first().json.jdText } }];

